{
  "entities": [
    {
      "name": "Mô hình quá phức tạp",
      "node_type": "concept",
      "description_draft": "Một nguyên nhân gây ra quá khớp khi lớp mô hình chứa các hàm quá phức tạp, cho phép khớp hoàn hảo với tập huấn luyện nhưng kém tổng quát.",
      "evidence": "Mô hình quá phức tạp: nghĩa là mỗi hàm trong lớp mô hình H quá phức tạp.",
      "media_evidence_id": "",
      "learnable": true,
      "aliases": []
    },
    {
      "name": "Nhiễu hoặc lỗi trong dữ liệu",
      "node_type": "concept",
      "description_draft": "Các sai lệch trong dữ liệu huấn luyện khiến thuật toán học tìm ra hàm không tốt.",
      "evidence": "Nhiễu hoặc lỗi trong dữ liệu: nhiễu hoặc lỗi có thể làm sai lệch thông tin ẩn chứa trong các mẫu dữ liệu.",
      "media_evidence_id": "",
      "learnable": true,
      "aliases": []
    },
    {
      "name": "Tập học quá bé",
      "node_type": "concept",
      "description_draft": "Tình trạng tập dữ liệu huấn luyện có kích thước nhỏ, không đại diện tốt cho toàn bộ không gian dữ liệu, dẫn đến mô hình học kém.",
      "evidence": "Tập học quá bé: khi đó một mô hình dễ dàng có thể xấp xỉ tập học một cách hoàn hảo.",
      "media_evidence_id": "",
      "learnable": true,
      "aliases": []
    }
  ],
  "edges": [
    {
      "source": "Mô hình quá phức tạp",
      "target": "Quá khớp",
      "edge_type": "causes",
      "evidence": "Có nhiều nguyên nhân dẫn đến vấn đề quá khớp. Chẳng hạn, Mô hình quá phức tạp"
    },
    {
      "source": "Nhiễu hoặc lỗi trong dữ liệu",
      "target": "Quá khớp",
      "edge_type": "causes",
      "evidence": "Nhiễu hoặc lỗi trong dữ liệu: nhiễu hoặc lỗi có thể làm sai lệch thông tin ẩn chứa trong các mẫu dữ liệu. Do đó thuật toán học dễ bị đánh lừa và tìm ra hàm không tốt trong H ."
    },
    {
      "source": "Tập học quá bé",
      "target": "Quá khớp",
      "edge_type": "causes",
      "evidence": "Tập học quá bé: khi đó một mô hình dễ dàng có thể xấp xỉ tập học một cách hoàn hảo."
    }
  ],
  "media_descriptions": []
}

